import {AppError} from '@crew/shared';
import {publicNotification,notificationRows,preferences} from './notifications.js';
import {digestTime,nextDigestAt} from './digest-cadence.js';
export function digestSummary(items) {
  return items.map(item=>{
    const event=item.activity,entity=event.after??event.before??{};
    return [event.time,entity.key??entity.title??entity.name??event.entityType,event.action,item.reason].join(' — ');
  }).join('\n');
}
function candidates(ctx,userId,orgId,pref) {
  return notificationRows(ctx,userId,{orgId,state:'unread'})
    .filter(row=>!row.digested_at&&(!pref.mentionsOnly||row.reason==='mention'));
}
export function queueDigestBatch(ctx,userId,orgId,{at=ctx.now(),automatic=false,expectedDue}={}) {
  at=digestTime(at);
  return ctx.transaction(()=>{
    ctx.db.prepare(`INSERT OR IGNORE INTO notification_preferences
      (user_id,org_id,email_enabled,mentions_only,updated_at) VALUES (?,?,1,0,?)`).run(userId,orgId,at);
    const pref=preferences(ctx,userId,orgId),schedule=pref.digestSchedule;
    if(automatic&&(!pref.emailEnabled||pref.digestFrequency==='manual'||schedule.status==='error'||
      !schedule.nextRunAt||schedule.nextRunAt>at||(expectedDue&&schedule.nextRunAt!==expectedDue)))return {digest:null,count:0,remaining:0,skipped:true};
    if(!pref.emailEnabled)throw new AppError('CONFLICT','Email digests are disabled in your preferences',409);
    if(!ctx.permissions.canOrg(userId,orgId,'org:read')) {
      if(!automatic)throw new AppError('FORBIDDEN','Organization permission denied',403);
      ctx.db.prepare("UPDATE notification_preferences SET digest_next_at=NULL,digest_status='access-lost',digest_remaining=0 WHERE user_id=? AND org_id=?").run(userId,orgId);
      return {digest:null,count:0,remaining:0,skipped:true};
    }
    const available=candidates(ctx,userId,orgId,pref),rows=available.slice(0,200);
    const items=rows.map(row=>publicNotification(ctx,row));
    const user=ctx.db.prepare('SELECT email FROM users WHERE id=?').get(userId);
    let digest=null;
    if(rows.length) {
      const queued=ctx.enqueueOutbox({orgId,userId,kind:'digest',toEmail:user.email,
        subject:'Crew: '+rows.length+' unread updates',textBody:digestSummary(items),
        payload:{notificationIds:rows.map(row=>row.id),count:rows.length}});
      for(const row of rows)ctx.db.prepare('UPDATE notifications SET digested_at=? WHERE id=? AND user_id=? AND digested_at IS NULL').run(at,row.id,userId);
      digest={id:queued.id,orgId,count:rows.length,createdAt:queued.createdAt,items};
    }
    const remaining=available.length-rows.length;
    const suspended=schedule.status==='error';
    const status=suspended?'error':pref.digestFrequency==='manual'?'manual':remaining?'backlog':rows.length?'scheduled':'idle';
    ctx.db.prepare(`UPDATE notification_preferences SET digest_last_at=?,digest_last_id=COALESCE(?,digest_last_id),
      digest_remaining=?,digest_status=?,digest_error=?,digest_next_at=? WHERE user_id=? AND org_id=?`)
      .run(at,digest?.id??null,remaining,status,suspended?schedule.lastError:null,suspended?null:nextDigestAt(pref.digestFrequency,at,remaining),userId,orgId);
    return {digest,count:rows.length,remaining};
  });
}
export function emitDigestQueued(ctx,userId,orgId,result) {
  if(result.digest)ctx.bus.emit({actorId:userId,userId,orgId,entityType:'digest',entityId:result.digest.id,
    action:'queued',before:null,after:{count:result.count},time:ctx.now()});
}

export const DIGEST_FREQUENCIES=Object.freeze(['manual','15-minute','hourly','daily']);
const durations={'15-minute':15*60*1000,hourly:60*60*1000,daily:24*60*60*1000};
export const DIGEST_TICK_MS=15000;
export function digestTime(value) {
  const time=Date.parse(value);
  if(!Number.isFinite(time))throw new TypeError('Digest clock must be an ISO timestamp');
  return new Date(time).toISOString();
}
export function nextDigestAt(frequency,at,remaining=0) {
  if(frequency==='manual')return null;
  return new Date(Date.parse(digestTime(at))+(remaining?DIGEST_TICK_MS:durations[frequency])).toISOString();
}
export function digestSchedule(row) {
  const frequency=row?.digest_frequency??'manual';
  const enabled=row?Boolean(row.email_enabled):true;
  return {frequency,nextRunAt:enabled&&frequency!=='manual'?row?.digest_next_at??null:null,
    lastRunAt:row?.digest_last_at??null,lastDigestId:row?.digest_last_id??null,
    status:!enabled?'disabled':frequency==='manual'?'manual':row?.digest_status??'scheduled',
    remaining:row?.digest_remaining??0,lastError:row?.digest_error??null};
}

import {queueDigestBatch,emitDigestQueued} from './digest-batch.js';
import {digestTime,DIGEST_TICK_MS} from './digest-cadence.js';
export function runDueDigests(ctx,at=ctx.now()) {
  at=digestTime(at);
  const due=ctx.db.prepare(`SELECT user_id,org_id,digest_next_at FROM notification_preferences
    WHERE email_enabled=1 AND digest_frequency<>'manual' AND digest_status<>'error'
      AND digest_next_at IS NOT NULL AND digest_next_at<=?
    ORDER BY digest_next_at,user_id,org_id LIMIT 20`).all(at);
  const outcomes=[];
  for(const row of due) {
    try {
      const result=queueDigestBatch(ctx,row.user_id,row.org_id,{at,automatic:true,expectedDue:row.digest_next_at});
      emitDigestQueued(ctx,row.user_id,row.org_id,result);
      outcomes.push({userId:row.user_id,orgId:row.org_id,...result});
    }catch(error) {
      const message='Digest outcome requires review; automatic batching is suspended. Save cadence settings deliberately to resume.';
      ctx.db.prepare("UPDATE notification_preferences SET digest_status='error',digest_error=?,digest_next_at=NULL WHERE user_id=? AND org_id=?")
        .run(message,row.user_id,row.org_id);
      outcomes.push({userId:row.user_id,orgId:row.org_id,status:'error',error:message,code:error.code??'FAILED'});
    }
  }
  return {at,considered:due.length,outcomes};
}
export function startDigestService(ctx,{run=runDueDigests,setTimer=setInterval,clearTimer=clearInterval,intervalMs=DIGEST_TICK_MS}={}) {
  let stopped=false,running=false,timer;
  const state={status:'idle',lastRunAt:null,lastError:null};
  async function tick() {
    if(stopped||running||state.status==='error')return false;
    running=true;state.status='running';
    try {
      await run(ctx,ctx.now());
      if(!stopped){state.status='idle';state.lastRunAt=ctx.now();}
      return true;
    }catch(error) {
      state.lastError='Digest service stopped after an uncertain error; restart only after review.';
      state.status='error';stopped=true;clearTimer(timer);
      return false;
    }finally{running=false;}
  }
  function stop(){stopped=true;clearTimer(timer);if(state.status!=='error')state.status='stopped';}
  timer=setTimer(()=>{void tick();},intervalMs);
  timer?.unref?.();
  const service={tick,stop,state};
  ctx.digestService=service;
  (ctx.cleanups??=[]).push(stop);
  return service;
}

import {fields,validation} from '@crew/shared';
import {publicNotification,notificationRows} from './notifications.js';
import {digestSummary,queueDigestBatch,emitDigestQueued} from './digest-batch.js';
export {digestSummary} from './digest-batch.js';
export function visibleDigest(ctx,userId,row,visible) {
  if(row.kind!=='digest'||row.user_id!==userId||!ctx.permissions.membership(userId,row.org_id))return null;
  const notifications=visible??new Map(notificationRows(ctx,userId,{orgId:row.org_id}).map(item=>[item.id,item]));
  const payload=JSON.parse(row.payload_json);
  const items=(payload.notificationIds??[]).map(id=>notifications.get(id)).filter(Boolean).map(item=>publicNotification(ctx,item));
  return {id:row.id,orgId:row.org_id,createdAt:row.created_at,count:items.length,items,textBody:digestSummary(items)};
}
export function createDigest(ctx,req,orgId) {
  ctx.permissions.assertSelf(req,req.user.id,'insight:write');
  ctx.permissions.assertOrg(req,orgId,'org:read');
  const result=queueDigestBatch(ctx,req.user.id,orgId);
  emitDigestQueued(ctx,req.user.id,orgId,result);
  return result;
}

export function registerDigestRoutes(ctx) {
  const {app,requireAuth,permissions:p}=ctx;
  app.post('/api/v1/digests',requireAuth,(req,res)=>{
    fields(req.body,['orgId']);if(typeof req.body.orgId!=='string')throw validation({orgId:'Choose an organization'});
    const result=createDigest(ctx,req,req.body.orgId);res.status(result.digest?201:200).json(result);
  });
  app.get('/api/v1/digests',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:read');
    if(req.query.orgId)p.assertOrg(req,req.query.orgId,'org:read');
    const visible=new Map(notificationRows(ctx,req.user.id,{orgId:req.query.orgId}).map(row=>[row.id,row]));
    const rows=ctx.db.prepare("SELECT * FROM outbox WHERE user_id=? AND kind='digest' ORDER BY created_at DESC,id").all(req.user.id)
      .filter(row=>!req.query.orgId||row.org_id===req.query.orgId)
      .map(row=>visibleDigest(ctx,req.user.id,row,visible)).filter(Boolean);
    res.json(ctx.paginate(rows,req.query));
  });
}

import {DIGEST_FREQUENCIES,digestSchedule,nextDigestAt} from './digest-cadence.js';
import {emitPersonal} from './personal-events.js';
import {AppError,validation,fields,uniqueIds} from '@crew/shared';
import {publicActivity,canSeeActivity} from './activity.js';
import {automaticSubscriptions,canReadProject} from './subscriptions.js';
export function preferences(ctx,userId,orgId) {
  const row=ctx.db.prepare('SELECT * FROM notification_preferences WHERE user_id=? AND org_id=?').get(userId,orgId);
  return {orgId,emailEnabled:row?Boolean(row.email_enabled):true,mentionsOnly:row?Boolean(row.mentions_only):false,
    digestFrequency:row?.digest_frequency??'manual',digestSchedule:digestSchedule(row)};
}
export function publicNotification(ctx,row) {
  const event=ctx.db.prepare('SELECT * FROM activity WHERE id=?').get(row.activity_id);
  return {id:row.id,orgId:row.org_id,projectId:row.project_id,reason:row.reason,
    readAt:row.read_at,read:Boolean(row.read_at),isRead:Boolean(row.read_at),createdAt:row.created_at,
    activity:publicActivity(event)};
}
export function notificationRows(ctx,userId,query={}) {
  if(query.state&&!['all','unread','read'].includes(query.state))throw validation({state:'Choose all, unread or read'});
  return ctx.db.prepare('SELECT n.* FROM notifications n WHERE n.user_id=? ORDER BY n.created_at DESC,n.id DESC').all(userId)
    .filter(row=>!query.orgId||row.org_id===query.orgId)
    .filter(row=>!query.projectId||row.project_id===query.projectId)
    .filter(row=>query.state==='read'?Boolean(row.read_at):query.state==='unread'?!row.read_at:true)
    .filter(row=>canReadProject(ctx,userId,row.project_id))
    .filter(row=>canSeeActivity(ctx,userId,ctx.db.prepare('SELECT * FROM activity WHERE id=?').get(row.activity_id)));
}
export function notifyActivity(ctx,event,activity) {
  const {issueId,mentioned}=automaticSubscriptions(ctx,event);
  if(!event.projectId||!activity)return;
  const watchers=ctx.db.prepare(`SELECT * FROM subscriptions WHERE project_id=? AND reason<>'muted'
    AND ((target_type='project' AND target_id=?) OR (target_type='issue' AND target_id=?))`).all(event.projectId,event.projectId,issueId??'');
  const users=new Map(watchers.map(row=>[row.user_id,'watching']));
  for(const userId of mentioned)users.set(userId,'mention');
  const after=event.after;
  if(event.entityType==='issue'&&after?.assigneeId&&after.assigneeId!==event.before?.assigneeId)users.set(after.assigneeId,'assignment');
  for(const [userId,reason] of users) {
    if(userId===event.actorId||!canReadProject(ctx,userId,event.projectId))continue;
    if(preferences(ctx,userId,event.orgId).mentionsOnly&&reason!=='mention')continue;
    const row=ctx.db.prepare('SELECT * FROM activity WHERE id=?').get(activity.id);
    if(!canSeeActivity(ctx,userId,row))continue;
    ctx.db.prepare(`INSERT OR IGNORE INTO notifications
      (id,user_id,org_id,project_id,activity_id,reason,created_at) VALUES (?,?,?,?,?,?,?)`)
      .run(ctx.id(),userId,event.orgId,event.projectId,event.id,reason,event.time);
  }
}
export function registerNotificationRoutes(ctx) {
  const {app,requireAuth,permissions:p}=ctx;
  app.get('/api/v1/notifications',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:read');
    if(req.query.orgId)p.assertOrg(req,req.query.orgId,'org:read');
    if(req.query.projectId)p.assertProject(req,req.query.projectId,'insight:read');
    const rows=notificationRows(ctx,req.user.id,req.query);
    const all=notificationRows(ctx,req.user.id,{orgId:req.query.orgId,projectId:req.query.projectId});
    res.json({...ctx.paginate(rows.map(row=>publicNotification(ctx,row)),req.query),unread:all.filter(row=>!row.read_at).length});
  });
  app.patch('/api/v1/notifications/:notificationId',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:write');fields(req.body,['read']);
    if(typeof req.body.read!=='boolean')throw validation({read:'Expected true or false'});
    const row=notificationRows(ctx,req.user.id).find(item=>item.id===req.params.notificationId);
    if(!row)throw new AppError('NOT_FOUND','Notification not found',404);
    ctx.db.prepare('UPDATE notifications SET read_at=? WHERE id=? AND user_id=?').run(req.body.read?ctx.now():null,row.id,req.user.id);
    emitPersonal(ctx,req,{orgId:row.org_id,projectId:row.project_id,entityType:'notification',entityId:row.id,action:req.body.read?'read':'unread',before:{read:Boolean(row.read_at)},after:{read:req.body.read}});
    res.json({notification:publicNotification(ctx,ctx.db.prepare('SELECT * FROM notifications WHERE id=?').get(row.id))});
  });
  app.post('/api/v1/notifications/mark',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:write');fields(req.body,['ids','all','orgId','read']);
    if(typeof req.body.read!=='boolean')throw validation({read:'Expected true or false'});
    if(req.body.orgId)p.assertOrg(req,req.body.orgId,'org:read');
    if(req.body.all!==true&&req.body.ids===undefined)throw validation({ids:'Select notification ids or all=true'});
    if(req.body.all===true&&req.body.ids!==undefined)throw validation({ids:'Use ids or all, not both'});
    const ids=req.body.all===true?null:new Set(uniqueIds(req.body.ids,'ids',{max:200}));
    const visible=notificationRows(ctx,req.user.id,{orgId:req.body.orgId});
    if(ids&&[...ids].some(id=>!visible.some(row=>row.id===id)))throw validation({ids:'Every notification must belong to your visible inbox'});
    const rows=visible.filter(row=>!ids||ids.has(row.id)),readAt=req.body.read?ctx.now():null;
    ctx.transaction(()=>{for(const row of rows)ctx.db.prepare('UPDATE notifications SET read_at=? WHERE id=? AND user_id=?').run(readAt,row.id,req.user.id);});
    for(const row of rows)emitPersonal(ctx,req,{orgId:row.org_id,projectId:row.project_id,entityType:'notification',entityId:row.id,action:req.body.read?'read':'unread',after:{read:req.body.read}});
    res.json({changed:rows.length,read:req.body.read});
  });
  app.get('/api/v1/notification-preferences',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:read');p.assertOrg(req,req.query.orgId,'org:read');
    res.json({preferences:preferences(ctx,req.user.id,req.query.orgId)});
  });
  app.patch('/api/v1/notification-preferences',requireAuth,(req,res)=>{
    p.assertSelf(req,req.user.id,'insight:write');fields(req.body,['orgId','emailEnabled','mentionsOnly','digestFrequency']);p.assertOrg(req,req.body.orgId,'org:read');
    const current=preferences(ctx,req.user.id,req.body.orgId);
    for(const key of ['emailEnabled','mentionsOnly'])if(req.body[key]!==undefined&&typeof req.body[key]!=='boolean')throw validation({[key]:'Expected true or false'});
    if(req.body.digestFrequency!==undefined&&!DIGEST_FREQUENCIES.includes(req.body.digestFrequency))throw validation({digestFrequency:'Choose manual, 15-minute, hourly or daily'});
    const next={...current,...req.body},at=ctx.now();
    const reset=req.body.digestFrequency!==undefined||req.body.emailEnabled!==undefined;
    const nextAt=!next.emailEnabled?null:reset?nextDigestAt(next.digestFrequency,at):current.digestSchedule.nextRunAt;
    const status=!next.emailEnabled?'disabled':next.digestFrequency==='manual'?'manual':reset?'scheduled':current.digestSchedule.status;
    ctx.transaction(()=>{
      ctx.db.prepare(`INSERT INTO notification_preferences
        (user_id,org_id,email_enabled,mentions_only,updated_at,digest_frequency,digest_next_at,digest_status)
        VALUES (?,?,?,?,?,?,?,?) ON CONFLICT(user_id,org_id) DO UPDATE SET
        email_enabled=excluded.email_enabled,mentions_only=excluded.mentions_only,updated_at=excluded.updated_at,
        digest_frequency=excluded.digest_frequency,digest_next_at=excluded.digest_next_at,digest_status=excluded.digest_status,
        digest_error=CASE WHEN ? THEN NULL ELSE digest_error END`)
        .run(req.user.id,next.orgId,Number(next.emailEnabled),Number(next.mentionsOnly),at,next.digestFrequency,nextAt,status,Number(reset));
    });
    emitPersonal(ctx,req,{orgId:next.orgId,entityType:'notificationPreference',entityId:req.user.id,action:'updated',before:current,after:next});
    res.json({preferences:preferences(ctx,req.user.id,next.orgId)});
  });
}

